    30→import { Platform } from 'react-native';
    31→import * as FileSystem from 'expo-file-system/legacy';
    32→import * as VideoThumbnails from 'expo-video-thumbnails';
    33→import { Image as ExpoImage } from 'expo-image';
    34→import AsyncStorage from '@react-native-async-storage/async-storage';
    35→import * as SafReaderModule from '@/modules/saf-reader';
    36→
    37→export type ThumbItemType = 'image' | 'video';
    38→
    39→export interface ThumbItem {
    40→  id: string;
    41→  uri: string;
    42→  type: ThumbItemType;
    43→}
    44→
    45→const STORAGE_KEY = '@statusvault_thumb_cache_v1';
    46→// FileSystem.cacheDirectory is wiped by the OS under storage pressure — the
    47→// queue will simply regenerate on the next scan, so this is the right place.
    48→const CACHE_DIR_NAME = 'status-thumbs/';
    49→
    50→// Module state — single instance per JS context (no React rerenders).
    51→let cacheDir: string | null = null;
    52→let memMap: Record<string, string> = {};
    53→const imagesPrefetched = new Set<string>();
    54→const subs = new Map<string, Set<(p: string | null) => void>>();
    55→let queue: ThumbItem[] = [];
    56→let processing = false;
    57→let cancelToken = 0;
    58→let initPromise: Promise<void> | null = null;
    59→let persistTimer: ReturnType<typeof setTimeout> | null = null;
    60→
    61→function safeFilename(id: string): string {
    62→  return id.replace(/[^a-zA-Z0-9._-]/g, '_').slice(0, 120);
    63→}
    64→
    65→function notify(id: string, path: string | null) {
    66→  const set = subs.get(id);
    67→  if (!set || set.size === 0) return;
    68→  set.forEach((cb) => {
    69→    try {
    70→      cb(path);
    71→    } catch {
    72→      // subscriber bug shouldn't take down the queue
    73→    }
    74→  });
    75→}
    76→
    77→function schedulePersist() {
    78→  if (persistTimer) return;
    79→  persistTimer = setTimeout(() => {
    80→    persistTimer = null;
    81→    AsyncStorage.setItem(STORAGE_KEY, JSON.stringify(memMap)).catch(() => {});
