    83→}
    84→
    85→async function ensureCacheDir(): Promise<string | null> {
    86→  if (cacheDir) return cacheDir;
    87→  const root = FileSystem.cacheDirectory;
    88→  if (!root) return null;
    89→  cacheDir = root + CACHE_DIR_NAME;
    90→  try {
    91→    const info = await FileSystem.getInfoAsync(cacheDir);
