   112→      }
   113→    } catch {
   114→      // corrupt JSON — start fresh
   115→      memMap = {};
   116→    }
   117→  })();
   118→  return initPromise;
   119→}
   120→
   121→function get(id: string): string | null {
   122→  return memMap[id] || null;
   123→}
