   140→async function generateOne(item: ThumbItem): Promise<void> {
   141→  // For an existing entry, double-check the file is still there. The OS can
   142→  // wipe the cache directory under storage pressure between sessions.
   143→  const existing = memMap[item.id];
   144→  if (existing) {
   145→    try {
   146→      const info = await FileSystem.getInfoAsync(existing);
   147→      if (info.exists && (info as any).size > 0) {
   148→        return; // still good — nothing to do
   149→      }
   150→    } catch {
   151→      // fall through and regenerate
   152→    }
   153→    delete memMap[item.id];
   154→  }
   155→
   156→  if (item.type === 'image') {
   157→    // For images we don't keep a separate file — expo-image's own disk
   158→    // cache is already a fast file-system lookup keyed by URI hash. We
   159→    // just warm it with a single prefetch call and from then on every
   160→    // grid render is a memory/disk hit, not a content:// round-trip.
   161→    if (imagesPrefetched.has(item.uri)) return;
   162→    imagesPrefetched.add(item.uri);
   163→    try {
   164→      await ExpoImage.prefetch(item.uri, 'memory-disk');
   165→    } catch {
   166→      // prefetch failure is harmless — Glide will still try on first paint
   167→    }
   168→    return;
   169→  }
   170→
   171→  // Videos: extract first key-frame as a JPG once and reuse forever.
   172→  //
   173→  // NATIVE PATH (EAS / custom build):
   174→  //   SafReaderModule.generateThumbnail runs Android's hardware-accelerated
   175→  //   MediaMetadataRetriever entirely in Java — no JS bridge overhead, no
   176→  //   second process hop. It writes atomically via .tmp+rename itself.
   177→  //   A 3 s timeout guards against the MediaMetadataRetriever hang seen on
   178→  //   MIUI / HyperOS and Samsung OneUI: setDataSource(context, uri) never
   179→  //   throws and never resolves for certain SAF content:// URIs, which
   180→  //   stalls the entire queue. On timeout we fall through to the JS path.
   181→  //
   182→  // JS FALLBACK (Expo Go / no native module / native timeout):
   183→  //   expo-video-thumbnails — also hardware-accelerated but crosses the
   184→  //   JS bridge twice (request + result) and writes to a temp dir that
   185→  //   we then have to move into our managed cache dir.
   186→  const dir = await ensureCacheDir();
   187→  if (!dir) return;
   188→  const dest = `${dir}vid_${safeFilename(item.id)}.jpg`;
   189→
   190→  // Helper: run expo-video-thumbnails and move result into managed dest.
   191→  async function jsThumb(): Promise<void> {
   192→    const tmp = `${dest}.tmp`;
   193→    const result = await VideoThumbnails.getThumbnailAsync(item.uri, {
   194→      time: 0,
   195→      quality: 0.5,
   196→    });
   197→    try { await FileSystem.deleteAsync(tmp, { idempotent: true }); } catch {}
   198→    await FileSystem.copyAsync({ from: result.uri, to: tmp });
   199→    try { await FileSystem.deleteAsync(dest, { idempotent: true }); } catch {}
   200→    await FileSystem.moveAsync({ from: tmp, to: dest });
   201→    try { await FileSystem.deleteAsync(result.uri, { idempotent: true }); } catch {}
   202→  }
   203→
   204→  try {
   205→    if (SafReaderModule.isAvailable()) {
   206→      // Native Java path with a hard 3 s timeout.
   207→      // If it resolves in time: done.  If it times out or throws: fall back
   208→      // to expo-video-thumbnails below so the queue never stalls.
   209→      let nativeOk = false;
   210→      try {
   211→        await Promise.race([
   212→          SafReaderModule.generateThumbnail(item.uri, dest, 0).then(() => { nativeOk = true; }),
   213→          new Promise<void>((_, reject) =>
   214→            setTimeout(() => reject(new Error('thumb_timeout')), 3000),
   215→          ),
   216→        ]);
   217→      } catch {
   218→        // Native timed out or threw — fall back to JS path.
   219→        __DEV__ && console.log('[ThumbnailCache] native thumb failed/timed-out, falling back:', item.id);
   220→      }
   221→      if (!nativeOk) {
   222→        // JS fallback — expo-video-thumbnails handles content:// via the
   223→        // Expo media module which uses ContentResolver correctly.
   224→        await jsThumb();
   225→      }
   226→    } else {
   227→      await jsThumb();
   228→    }
   229→    memMap[item.id] = dest;
   230→    schedulePersist();
   231→    notify(item.id, dest);
   232→  } catch {
   233→    // Codec error / unsupported container / both paths failed.
   234→    // Silently skip — the grid shows the blurhash placeholder for this
   235→    // item; the next loadStatuses() scan will retry.
   236→    __DEV__ && console.log('[ThumbnailCache] both paths failed for:', item.id);
   237→  }
   238→}
