   240→function enqueue(items: ThumbItem[]): void {
   241→  if (Platform.OS !== 'android') return; // only Android suffers this lag
   242→  if (!Array.isArray(items) || items.length === 0) return;
   243→  // Replace the queue — newest scan wins. Anything from the previous scan
   244→  // that's still relevant will be picked up again from memMap (skipped if
   245→  // already present, generated otherwise).
   246→  queue = items.slice();
   247→  processQueue();
   248→}
   249→
   250→async function processQueue(): Promise<void> {
   251→  if (processing) return;
   252→  processing = true;
   253→  const myToken = ++cancelToken;
   254→  try {
   255→    await init();
   256→    while (queue.length > 0 && cancelToken === myToken) {
   257→      const next = queue.shift();
   258→      if (!next) break;
   259→      await generateOne(next);
   260→      // Idle gap between items. ~150 ms keeps the JS thread fully available
   261→      // for touch / scroll handlers — the user's input always wins over
   262→      // background thumbnail work.
   263→      await new Promise((r) => setTimeout(r, 150));
   264→    }
   265→  } finally {
   266→    processing = false;
   267→    // If items were enqueued while we were processing (e.g. after a cancel
   268→    // that stopped the loop early but left new items in the queue), kick
   269→    // off a fresh cycle now that processing is free.
   270→    if (queue.length > 0) {
   271→      // Use setTimeout(0) to yield before re-entering so the call stack
   272→      // never grows unboundedly and React can batch any pending state updates.
   273→      setTimeout(processQueue, 0);
   274→    }
   275→  }
   276→}
   277→
   278→function cancel(): void {
   279→  cancelToken++;
   280→  queue = [];
   281→  // Do NOT set processing = false here. The running processQueue loop will
   282→  // see cancelToken !== myToken on its next iteration, exit cleanly, and
   283→  // set processing = false itself in its finally block.
   284→  // Setting processing = false here creates a race: if enqueue() is called
   285→  // before the old processQueue's finally runs, a second processQueue starts
   286→  // in parallel, and then the first finally sets processing = false again,
   287→  // allowing a third — duplicate runs corrupt the queue order.
   288→}
   289→
   290→async function prune(currentIds: Set<string>): Promise<void> {
   291→  await init();
   292→  let dirty = false;
   293→  for (const id of Object.keys(memMap)) {
   294→    if (!currentIds.has(id)) {
   295→      const path = memMap[id];
   296→      try {
   297→        await FileSystem.deleteAsync(path, { idempotent: true });
   298→      } catch {}
   299→      delete memMap[id];
   300→      dirty = true;
   301→    }
   302→  }
   303→  if (dirty) schedulePersist();
   304→}
   305→
   306→/**
   307→ * pause() — stop the thumbnail queue immediately.
   308→ * Call this when the video viewer opens so thumbnail I/O (which decodes
   309→ * video key-frames via MediaMetadataRetriever) does NOT compete with the
   310→ * video player for the hardware decoder and storage bandwidth.
   311→ *
   312→ * The queue is simply cancelled; any pending items will be re-enqueued
   313→ * when loadStatuses() runs after the viewer closes.  Already-generated
   314→ * thumbnails in memMap are unaffected.
   315→ */
   316→function pause(): void {
   317→  cancel();
   318→}
   319→
   320→export const ThumbnailCache = {
   321→  init,
   322→  get,
   323→  subscribe,
   324→  enqueue,
   325→  cancel,
   326→  pause,
   327→  prune,
   328→};
