/**
 * VideoPlayerView — expo-video wrapper for the status viewer.
 *
 * ANDROID 11+ FREEZE ROOT CAUSE & FIX
 * ────────────────────────────────────
 * The original code called player.play() in THREE places:
 *   1. useVideoPlayer initializer  → sets playWhenReady=true immediately
 *   2. statusChange → readyToPlay  → second play() when ready
 *   3. timeUpdate stall recovery   → pause()+play() at ~1s
 *
 * On Android 11+ Media3, the decoder warm-up takes 800ms–1.5s. During
 * this window the SurfaceTexture is being attached to ExoPlayer's codec.
 * Any play()/pause() call that arrives while the surface is mid-attach
 * can leave the Media3 pipeline stuck — the decoder acquires its input
 * buffer slot but never gets the signal to start draining it.
 *
 * Fix: play() is called in EXACTLY ONE place — the readyToPlay handler.
 * The initializer does NOT call p.play(). The stall recovery is gone.
 * On swipe-back, player.play() is safe because readyToPlay has already
 * fired (the MediaItem is still loaded) — no surface re-attachment race.
 *
 * timeUpdateEventInterval = 0.5s (2 events/sec). Enough for the
 * thumbnail-fade callback. The old 0.1s (10/sec) flooded the JS thread
 * during the codec init window and worsened jank on mid-range devices.
 */
import React, { useEffect, useRef, useCallback } from 'react';
import { StyleSheet } from 'react-native';
import { VideoView, useVideoPlayer } from 'expo-video';

interface VideoPlayerViewProps {
  fileUri: string;
  isActive: boolean;
  onPlaying: () => void;
  onError: (message: string) => void;
}

let _mountedCount = 0;
export function getActiveMountedCount(): number { return _mountedCount; }

export const VideoPlayerView = React.memo(function VideoPlayerView({
  fileUri,
  isActive,
  onPlaying,
  onError,
}: VideoPlayerViewProps) {
  const isActiveRef = useRef(isActive);
  isActiveRef.current = isActive;

  const hasCalledOnPlaying = useRef(false);
  const didMountRef = useRef(false);
  const pauseTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  // Tracks whether readyToPlay has fired for the current file.
  // Reset on swipe-back so that if the player was released and re-mounted
  // for a new URI, play() will be called again via readyToPlay.
  const readyFiredRef = useRef(false);

  const player = useVideoPlayer({ uri: fileUri }, (p) => {
    p.loop = true;
    p.muted = false;
    p.timeUpdateEventInterval = 0.5;
    // DO NOT call p.play() here.
    // Calling play() before the SurfaceTexture is attached causes Android 11+
    // Media3 to enter a broken state where the decoder prepares and renders
    // one frame but never advances. readyToPlay fires after surface attachment
    // is complete and is the only safe point to begin playback.
  });

  const confirmPlaying = useCallback(() => {
    if (hasCalledOnPlaying.current) return;
    hasCalledOnPlaying.current = true;
    onPlaying();
  }, [onPlaying]);

  useEffect(() => {
    _mountedCount++;

    const timeUpdateSub = player.addListener('timeUpdate', (event: any) => {
      const time = event.currentTime ?? 0;
      if (time > 0) confirmPlaying();
    });

    const statusSub = player.addListener('statusChange', (event: any) => {
      if (event.status === 'error') {
        onError(event.error?.message ?? 'Playback error');
        return;
      }
      if (event.status === 'readyToPlay' && isActiveRef.current && !readyFiredRef.current) {
        // Play exactly once per file load, after Media3 confirms the
        // decoder and surface are both fully ready.
        readyFiredRef.current = true;
        try { player.play(); } catch {}
      }
    });

    return () => {
      timeUpdateSub.remove();
      statusSub.remove();
      if (pauseTimerRef.current) {
        clearTimeout(pauseTimerRef.current);
        pauseTimerRef.current = null;
      }
      try { player.release(); } catch {}
      _mountedCount--;
    };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  // Pause on swipe-away (400ms debounce absorbs FlatList transient flickers);
  // resume on swipe-back. readyToPlay has already fired for this file so a
  // direct play() call is safe here — no second surface-attach race.
  useEffect(() => {
    if (!didMountRef.current) {
      didMountRef.current = true;
      return;
    }

    if (pauseTimerRef.current) {
      clearTimeout(pauseTimerRef.current);
      pauseTimerRef.current = null;
    }

    if (isActive) {
      hasCalledOnPlaying.current = false;
      // readyFiredRef stays true — file is already loaded, play() is safe.
      try { if (!player.playing) player.play(); } catch {}
    } else {
      pauseTimerRef.current = setTimeout(() => {
        pauseTimerRef.current = null;
        if (!isActiveRef.current) {
          try { player.pause(); } catch {}
        }
      }, 400);
    }
  }, [isActive]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <VideoView
      player={player}
      style={StyleSheet.absoluteFill}
      nativeControls={false}
      contentFit="cover"
    />
  );
});

/**
 * ViewerItem — single slide in the full-screen status viewer.
 *
 * VIDEO PLAYER ARCHITECTURE (Android 11+ SAF)
 * ───────────────────────────────────────────
 * The custom native ExoPlayerView module requires Java source files at
 * modules/exo-player/android/ that are not present in this repo, so
 * UIManager.hasViewManagerConfig('ExoPlayerView') always returns false
 * and the module is always unavailable. All video playback therefore goes
 * through expo-video (VideoPlayerView). The ExoPlayerView/ExoPlayerBoundary
 * code has been removed to eliminate the state changes (nativePlayerFailed,
 * exoPaused) they caused — those state updates triggered ViewerItem re-renders
 * while a video was playing, which detached and reattached the VideoView's
 * SurfaceTexture and contributed to the Android 11+ freeze.
 *
 * URI PREPARATION
 * ───────────────
 * SAF content:// URIs are always copied to a local file:// path before
 * the player mounts (prepareStatusForViewing with forPlayback:true).
 * hasPreparedRef tracks whether preparation is in progress or complete
 * for the current item so the prepare effect never fires twice, even if
 * isNearActive/isActive toggle while the async copy is running.
 */
import React, {
  useState,
  useRef,
  useCallback,
  useEffect,
  useMemo,
} from 'react';
import {
  View,
  StyleSheet,
  Animated,
  Text,
  TouchableOpacity,
} from 'react-native';
import { GestureDetector, Gesture } from 'react-native-gesture-handler';
import Reanimated, {
  useSharedValue,
  useAnimatedStyle,
  withSpring,
  withDecay,
  runOnJS,
} from 'react-native-reanimated';
import { Image } from 'expo-image';
import { VideoPlayerView, getActiveMountedCount } from './VideoPlayerView';
import { Ionicons } from '@expo/vector-icons';
import { useMedia, StatusItem, SavedItem } from '@/contexts/MediaContext';
import { useThemeColors } from '@/contexts/ThemeContext';
import { useThumbnail } from '@/hooks/media/useThumbnail';
import { createStyles, SW, SH } from './viewerStyles';

const VIEWER_PLACEHOLDER = { blurhash: 'L6PZfSi_.AyE_3t7t7R**0o#DgR4' };

export interface ViewerItemProps {
  item: StatusItem | SavedItem;
  isActive: boolean;
  isNearActive: boolean;
  onToggleControls: () => void;
  showControls: boolean;
  controlsOpacity: Animated.Value;
}

export function ViewerItem({
  item,
  isActive,
  isNearActive,
  onToggleControls,
}: ViewerItemProps) {
  const COLORS = useThemeColors();
  const styles = useMemo(() => createStyles(COLORS), [COLORS]);
  const { prepareStatusForViewing } = useMedia();

  const cachedThumb = useThumbnail(item.id);

  const [displayUri, setDisplayUri] = useState<string | null>(null);
  const [videoError, setVideoError] = useState<string | null>(null);

  // Thumbnail fades from 1→0 once video starts playing.
  const thumbnailOpacity = useRef(new Animated.Value(1)).current;
  const isVideoPlayingRef = useRef(false);

  // Tracks whether URI preparation has been initiated for the current item.
  // Using a ref (not state) means starting the async copy doesn't re-render
  // the component, which keeps the player unmolested during file I/O.
  const hasPreparedRef = useRef(false);
  const isActiveRef = useRef(isActive);
  isActiveRef.current = isActive;

  // ── Debounced video-player mount gate ────────────────────────────────────
  // Ensures totalActive=1 at all times — no competing decoders.
  //
  //   UNMOUNT — 32ms debounce when isActive → false
  //     Transient FlatList flickers (16ms) cancel before firing → no unmount.
  //     Real swipe-aways stay false → fires → player gone.
  //
  //   MOUNT — immediate if no other player alive; 64ms delay otherwise
  //     If count=0 the decoder is free → mount now.
  //     If count>0 the old player is still in its 32ms unmount window →
  //     wait 64ms so the old player is guaranteed gone first.
  const [videoPlayerMounted, setVideoPlayerMounted] = useState(isActive);
  const videoMountTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    if (videoMountTimerRef.current) {
      clearTimeout(videoMountTimerRef.current);
      videoMountTimerRef.current = null;
    }

    if (isActive) {
      const existingPlayers = getActiveMountedCount();
      if (existingPlayers === 0) {
        setVideoPlayerMounted(true);
      } else {
        videoMountTimerRef.current = setTimeout(() => {
          videoMountTimerRef.current = null;
          if (isActiveRef.current) setVideoPlayerMounted(true);
        }, 64);
      }
    } else {
      videoMountTimerRef.current = setTimeout(() => {
        videoMountTimerRef.current = null;
        if (!isActiveRef.current) setVideoPlayerMounted(false);
      }, 32);
    }

    return () => {
      if (videoMountTimerRef.current) {
        clearTimeout(videoMountTimerRef.current);
        videoMountTimerRef.current = null;
      }
    };
  }, [isActive]); // eslint-disable-line react-hooks/exhaustive-deps

  const initialSource = useMemo(() => {
    return 'localUri' in item ? (item as SavedItem).localUri : item.uri;
  }, [item.id]); // eslint-disable-line react-hooks/exhaustive-deps

  const isSAF = initialSource.startsWith('content://');

  // ── Reset everything when item changes ──────────────────────────────────
  useEffect(() => {
    hasPreparedRef.current = false;
    setDisplayUri(null);
    setVideoError(null);
    thumbnailOpacity.setValue(1);
    isVideoPlayingRef.current = false;

    // Reset the debounced video-player mount gate for the new item.
    if (videoMountTimerRef.current) {
      clearTimeout(videoMountTimerRef.current);
      videoMountTimerRef.current = null;
    }
    setVideoPlayerMounted(isActiveRef.current);
  }, [item.id]); // eslint-disable-line react-hooks/exhaustive-deps

  // Re-show thumbnail when slide becomes inactive so swipe-back looks right.
  useEffect(() => {
    if (item.type !== 'video') return;
    if (!isActive) {
      thumbnailOpacity.setValue(1);
      isVideoPlayingRef.current = false;
    }
  }, [isActive, item.type]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Prepare URI ──────────────────────────────────────────────────────────
  // hasPreparedRef gates this effect so it runs at most once per item.
  // displayUri is intentionally NOT in the dependency array — including it
  // caused React to run the effect cleanup (setting a cancel flag) every time
  // setDisplayUri was called, which silently dropped the copy result for
  // the next swipe-to-same-item scenario.
  useEffect(() => {
    if (!isNearActive) {
      if (!isActive) {
        // Fully out of the window — free the display URI so the player
        // is not mounted for off-screen items.
        setDisplayUri(null);
        setVideoError(null);
        hasPreparedRef.current = false;
      }
      return;
    }

    // Already started or completed preparation for this item.
    if (hasPreparedRef.current) return;

    // Don't start SAF copy until the slide is actually active.
    // Images are cheap and can be set immediately for adjacent slides.
    if (item.type !== 'image' && !isActive) return;

    hasPreparedRef.current = true;

    if (item.type === 'image') {
      setDisplayUri(initialSource);
      return;
    }

    if (!isSAF) {
      // Legacy file:// (saved items or Android ≤10 paths) — play directly.
      setDisplayUri(initialSource);
      return;
    }

    // SAF content:// video — MUST copy to local file:// before the player
    // mounts. ExoPlayer cannot reliably stream from the SAF ContentProvider
    // on Android 11+: the DocumentProvider process is too slow to refill
    // ExoPlayer's buffer, so playback freezes at ~1s every time.
    setVideoError(null);

    prepareStatusForViewing(item as StatusItem, { forPlayback: true })
      .then((fileUri) => {
        if (!hasPreparedRef.current) return; // cancelled by item change
        if (fileUri) {
          setDisplayUri(fileUri);
        } else {
          hasPreparedRef.current = false;
          setVideoError('Could not load video — tap to retry');
        }
      })
      .catch(() => {
        if (!hasPreparedRef.current) return;
        hasPreparedRef.current = false;
        setVideoError('Could not load video — tap to retry');
      });
  }, [initialSource, isSAF, item.id, isNearActive, isActive, prepareStatusForViewing]); // eslint-disable-line react-hooks/exhaustive-deps

  // ── Callbacks for VideoPlayerView ────────────────────────────────────────
  const handlePlaying = useCallback(() => {
    if (isVideoPlayingRef.current) return;
    isVideoPlayingRef.current = true;
    Animated.timing(thumbnailOpacity, {
      toValue: 0,
      duration: 180,
      useNativeDriver: true,
    }).start();
  }, [thumbnailOpacity]);

  const handleError = useCallback((_msg: string) => {
    setVideoError('Tap to retry');
  }, []);

  const handleRetry = useCallback(() => {
    // Reset ALL state so the prepare effect re-runs from scratch.
    hasPreparedRef.current = false;
    setVideoError(null);
    setDisplayUri(null);
    thumbnailOpacity.setValue(1);
    isVideoPlayingRef.current = false;
  }, [thumbnailOpacity]);

  const mediaUri = displayUri || initialSource;

  // ── Pinch-to-zoom for images ───────────────────────────────────────────
  const imageScale = useSharedValue(1);
  const savedScale = useSharedValue(1);
  const translateX = useSharedValue(0);
  const translateY = useSharedValue(0);
  const savedTranslateX = useSharedValue(0);
  const savedTranslateY = useSharedValue(0);

  useEffect(() => {
    imageScale.value = 1;
    savedScale.value = 1;
    translateX.value = 0;
    translateY.value = 0;
    savedTranslateX.value = 0;
    savedTranslateY.value = 0;
  }, [item.id, isActive]); // eslint-disable-line react-hooks/exhaustive-deps

  const pinchGesture = Gesture.Pinch()
    .onUpdate((e) => {
      imageScale.value = Math.min(Math.max(savedScale.value * e.scale, 1), 6);
    })
    .onEnd(() => {
      if (imageScale.value < 1.15) {
        imageScale.value = withSpring(1);
        translateX.value = withSpring(0);
        translateY.value = withSpring(0);
        savedScale.value = 1;
        savedTranslateX.value = 0;
        savedTranslateY.value = 0;
      } else {
        savedScale.value = imageScale.value;
        const maxX = ((imageScale.value - 1) * SW) / 2;
        const maxY = ((imageScale.value - 1) * SW) / 2;
        if (Math.abs(translateX.value) > maxX) {
          const cx = translateX.value > 0 ? maxX : -maxX;
          translateX.value = withSpring(cx);
          savedTranslateX.value = cx;
        }
        if (Math.abs(translateY.value) > maxY) {
          const cy = translateY.value > 0 ? maxY : -maxY;
          translateY.value = withSpring(cy);
          savedTranslateY.value = cy;
        }
      }
    });

  const panGesture = Gesture.Pan()
    .manualActivation(true)
    .onTouchesMove((_e, state) => {
      if (imageScale.value > 1) state.activate();
      else state.fail();
    })
    .onUpdate((e) => {
      const scale = imageScale.value;
      const maxX = ((scale - 1) * SW) / 2;
      const maxY = ((scale - 1) * SW) / 2;
      const newX = savedTranslateX.value + e.translationX * 0.72;
      const newY = savedTranslateY.value + e.translationY * 0.72;
      translateX.value = Math.max(-maxX, Math.min(maxX, newX));
      translateY.value = Math.max(-maxY, Math.min(maxY, newY));
    })
    .onEnd((e) => {
      const scale = imageScale.value;
      const maxX = ((scale - 1) * SW) / 2;
      const maxY = ((scale - 1) * SW) / 2;
      translateX.value = withDecay(
        { velocity: e.velocityX * 0.5, deceleration: 0.92, clamp: [-maxX, maxX] },
        () => { savedTranslateX.value = translateX.value; },
      );
      translateY.value = withDecay(
        { velocity: e.velocityY * 0.5, deceleration: 0.92, clamp: [-maxY, maxY] },
        () => { savedTranslateY.value = translateY.value; },
      );
    });

  const doubleTapGesture = Gesture.Tap()
    .numberOfTaps(2)
    .maxDuration(200)
    .onEnd((e) => {
      if (imageScale.value > 1) {
        imageScale.value = withSpring(1);
        translateX.value = withSpring(0);
        translateY.value = withSpring(0);
        savedScale.value = 1;
        savedTranslateX.value = 0;
        savedTranslateY.value = 0;
      } else {
        const target = 2.5;
        imageScale.value = withSpring(target);
        savedScale.value = target;
        const maxX = ((target - 1) * SW) / 2;
        const maxY = ((target - 1) * SW) / 2;
        const tapX = Math.max(-maxX, Math.min(maxX, (SW / 2 - e.x) * (target - 1)));
        const tapY = Math.max(-maxY, Math.min(maxY, (SH / 2 - e.y) * (target - 1)));
        translateX.value = withSpring(tapX);
        translateY.value = withSpring(tapY);
        savedTranslateX.value = tapX;
        savedTranslateY.value = tapY;
      }
    });

  const singleTapGesture = Gesture.Tap()
    .numberOfTaps(1)
    .onEnd(() => { runOnJS(onToggleControls)(); });

  const imageGesture = Gesture.Simultaneous(
    pinchGesture,
    panGesture,
    Gesture.Exclusive(doubleTapGesture, singleTapGesture),
  );

  const imageAnimatedStyle = useAnimatedStyle(() => ({
    transform: [
      { scale: imageScale.value },
      { translateX: translateX.value },
      { translateY: translateY.value },
    ],
  }));

  return (
    <View style={styles.itemContainer}>
      {item.type === 'image' ? (
        <GestureDetector gesture={imageGesture}>
          <Reanimated.View style={[StyleSheet.absoluteFill, imageAnimatedStyle]}>
            <Image
              source={{ uri: mediaUri }}
              style={styles.image}
              contentFit="contain"
              cachePolicy="memory-disk"
              transition={150}
              priority={isActive ? 'high' : 'low'}
              recyclingKey={item.id}
              allowDownscaling
              decodeFormat="rgb"
              placeholder={VIEWER_PLACEHOLDER}
              placeholderContentFit="cover"
            />
          </Reanimated.View>
        </GestureDetector>
      ) : (
        <View style={StyleSheet.absoluteFill}>
          <View style={styles.videoWrap}>

            {/* Video player — mounts only when this slide is active AND
                displayUri is ready (copy complete).
                key={displayUri}: fresh player instance for every new URI
                so swipe-back to same video always gets a clean state. */}
            {videoPlayerMounted && displayUri && (
              <VideoPlayerView
                key={displayUri}
                fileUri={displayUri}
                isActive={isActive}
                onPlaying={handlePlaying}
                onError={handleError}
              />
            )}

            {/* Thumbnail poster — covers the black frame while copy is in
                progress and while the decoder warms up. Fades to invisible
                once the first real frame is confirmed via timeUpdate > 0. */}
            <Animated.View
              style={[StyleSheet.absoluteFill, { opacity: thumbnailOpacity }]}
              pointerEvents="none"
            >
              <Image
                source={cachedThumb ? { uri: cachedThumb } : null}
                style={StyleSheet.absoluteFill}
                contentFit="contain"
                cachePolicy="memory-disk"
                transition={0}
                recyclingKey={item.id}
                placeholder={VIEWER_PLACEHOLDER}
                placeholderContentFit="cover"
              />
            </Animated.View>

            {/* Retry overlay — only shown on confirmed playback error */}
            {videoError && (
              <TouchableOpacity
                style={[
                  StyleSheet.absoluteFill,
                  {
                    justifyContent: 'center',
                    alignItems: 'center',
                    backgroundColor: 'rgba(0,0,0,0.65)',
                  },
                ]}
                onPress={handleRetry}
                activeOpacity={0.8}
              >
                <Ionicons name="refresh-circle-outline" size={52} color="#fff" />
                <Text style={{ color: '#fff', marginTop: 10, fontSize: 14 }}>
                  Tap to retry
                </Text>
              </TouchableOpacity>
            )}
          </View>
        </View>
      )}
    </View>
  );
}

