   134→// ── FULL FALLBACK CHAIN: Layer 3 → 4 → 5 ────────────────────────────────────
   135→// Called when Layers 1+2 (direct play + cache copy) have already failed.
   136→// `sourceUri` is the original content:// URI or any file:// URI we have.
   137→// `startAtLayer` lets callers skip layers that have already been tried.
   138→export async function runFallbackChain(
   139→  sourceUri: string,
   140→  id: string,
   141→  name: string,
   142→  type: 'video' | 'image' = 'video',
   143→  startAtLayer: VideoLayer = 3,
   144→): Promise<LayerResult> {
   145→  // Layer 3 ──────────────────────────────────────────────────────────────────
   146→  if (startAtLayer <= 3) {
   147→    const l3 = await runLayer3(sourceUri, id, name, type);
   148→    if (l3) return { uri: l3, openedExternally: false, layer: 3 };
   149→  }
   150→
   151→  // Layer 4: native intent ───────────────────────────────────────────────────
   152→  // Try with the original content:// URI first; it works on some OEMs where
   153→  // the MediaStore has it indexed. If we have a file:// from a failed L3
   154→  // partial copy, try that too (expo FileProvider covers app directories).
   155→  if (startAtLayer <= 4) {
   156→    const opened = await runLayer4(sourceUri);
   157→    if (opened) return { uri: null, openedExternally: true, layer: 4 };
   158→  }
   159→
   160→  // Layer 5: MediaLibrary save ───────────────────────────────────────────────
   161→  // We need a file:// to create the asset. Try a fresh Layer 3 copy first
   162→  // (documents dir), then fall back to saving the content:// URI directly.
   163→  if (startAtLayer <= 5) {
   164→    let fileForAsset: string | null = null;
   165→    if (!sourceUri.startsWith('file://')) {
   166→      fileForAsset = await runLayer3(sourceUri, id, name, type).catch(() => null);
   167→    } else {
   168→      fileForAsset = sourceUri;
   169→    }
   170→
   171→    const l5Uri = fileForAsset
   172→      ? await runLayer5(fileForAsset)
   173→      : await runLayer5(sourceUri);
   174→
   175→    if (l5Uri) return { uri: l5Uri, openedExternally: false, layer: 5 };
   176→  }
   177→
   178→  return {
   179→    uri: null,
   180→    openedExternally: false,
   181→    layer: 5,
   182→    error: 'All 5 layers exhausted',
   183→  };
   184→}
   185→
   186→// ── CLEANUP: Remove document cache files older than maxAgeMs ─────────────────
   187→export async function cleanupDocumentCache(maxAgeMs: number = 7 * 24 * 60 * 60 * 1000): Promise<void> {
   188→  try {
   189→    const docDir = FileSystem.documentDirectory;
   190→    if (!docDir) return;
   191→
   192→    const vcacheDir = `${docDir}vcache/`;
   193→    let files: string[];
   194→    try {
   195→      files = await FileSystem.readDirectoryAsync(vcacheDir);
   196→    } catch {
   197→      return;
   198→    }
   199→
   200→    const now = Date.now();
   201→    for (const file of files) {
   202→      const fileUri = `${vcacheDir}${file}`;
   203→      try {
   204→        const info = await FileSystem.getInfoAsync(fileUri);
   205→        const age = info.modificationTime
   206→          ? now - info.modificationTime * 1000
   207→          : now;
   208→        if (age > maxAgeMs) {
   209→          await FileSystem.deleteAsync(fileUri, { idempotent: true });
   210→        }
   211→      } catch {}
   212→    }
   213→  } catch {}
   214→}
